main.text:
input:
  scalar: {type: number, enum: [123456789012345678901234567890, 1.0]}
output: {}
graph:
  variables:
    huge: {type: integer, default: 123456789012345678901234567890}
    precise: {type: number, default: 1.0000000000000000000000000001}
    ordered:
      type: object
      additionalProperties: {type: integer}
      default: {"10": 10, "2": 2, "0": 0, a: 1}
  nodes:
    n: {input: [scalar], run: 'read variables.scalar'}
  edges: ['start -> n', 'n -> end']

input:
  items: {type: array, items: {type: string}}
output:
  results: {type: array, items: {type: string}}
graph:
  nodes:
    each:
      for_each: {source: items, item: item, index: idx}
      output: {results: {type: string}}
      graph:
        nodes:
          one:
            use: builtin:assign
            with: {input: {source: item}, output: {value: results}}
        edges: ['start -> one', 'one -> end']
  edges: ['start -> each', 'each -> end']

input:
  user:
    type: object
    properties:
      id: {type: integer}
      optional: {type: string}
    required: [id]
output: {}
graph:
  nodes:
    n:
      input: [user]
      branches: {ok: done, skip: {description: skip, output: []}}
      catch: {err: '*'}
      run: 'read variables.user.id.'
  edges: ['start -> n', 'n.ok -> end', 'n.skip -> end', 'n.err -> fail']

input: {}
input: {}
output: {}
run: work

input: {}
output: {x: {type: integer}}
graph:
  nodes:
    call:
      use: workflow:main
      with: {output: {x: x}}
  edges: ['start -> call', 'call -> end']

input: {}
output: {}
graph:
  nodes:
    bad: {run: '', extra: 1}
    good:
      graph:
        nodes:
          inner: {input: [missing], run: work}
        edges: ['start -> inner', 'inner -> end']
  edges: ['start -> good', 'good -> end', 'start -> bad -> end']

input: {}
output: {}
graph:
  nodes:
    a: {run: work, output: {x: {type: integer}}}
    b: {input: [x], run: 'read variables.x'}
  edges: ['start -> [a, b] -> end']

input: {maybe: {type: [integer, 'null']}}
output: {}
graph:
  variables:
    x: {type: integer, default: 1}
  nodes:
    un:
      use: builtin:unwrap
      with: {input: {source: maybe}, output: {value: x}}
    read: {input: [x], run: 'read variables.x'}
  edges: ['start -> un', 'un.some -> end', 'un.none -> read', 'read -> end']

input: {flag: {type: boolean}}
output: {}
graph:
  variables: {x: {type: integer, default: 0}}
  nodes:
    test: {input: [flag, x], branches: {again: continue, done: stop}, run: work}
    update:
      use: builtin:math
      with: {input: {op: {value: add}, left: x, right: 1}, output: {result: x}}
  edges: ['start -> test', 'test.again -> update', 'update -> test', 'test.done -> end']

input: {flag: {type: boolean}}
output: {}
graph:
  nodes:
    invert:
      use: builtin:logic
      with: {input: {op: {value: not}, source: flag}}
  edges: ['start -> invert', 'invert.true -> end', 'invert.false -> fail']

input: {array: {type: array, items: {type: string}}}
output: {}
graph:
  variables:
    item: {type: string}
    rest: {type: array, items: {type: string}}
  nodes:
    shift:
      use: builtin:array_shift
      with: {input: {source: array}, output: {item: item, rest: rest}}
  edges: ['start -> shift', 'shift.some -> end', 'shift.empty -> end']

input: !!map {}
output: {}
graph:
  variables:
    text: {type: string, default: !!str 01}
    integer: {type: integer, default: !!int '001'}
    float: {type: number, default: !!float 1}
    bool: {type: boolean, default: !!bool 'TRUE'}
    nil: {type: [string, 'null'], default: !!null null}
    array: {type: array, items: {type: string}, default: !!seq [a]}
    map: {type: object, additionalProperties: {type: integer}, default: !!map {x: 1}}
  nodes: {n: {run: !!str work}}
  edges: !!seq ['start -> n', 'n -> end']

input: {}
output: {}
run: !!bool yes
